-- PostgreSQL baseline of SQLite schema13. Generated from empty schema only.
-- USD minor units and IDs use exact BIGINT; JSON/date/timestamp text is preserved.
CREATE TABLE acc_account_profiles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id BIGINT NOT NULL,effective_date TEXT NOT NULL,name TEXT NOT NULL,reporting_type TEXT NOT NULL CHECK(reporting_type IN('asset','liability','net_assets','income','expense')),reporting_group TEXT NOT NULL,control_role TEXT NOT NULL DEFAULT '',active BIGINT NOT NULL CHECK(active IN(0,1)),cash_flow TEXT NOT NULL CHECK(cash_flow IN('operating','investing','financing','cash','noncash')),reason TEXT NOT NULL,actor_id BIGINT);
CREATE TABLE acc_asset_approvals(asset_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE acc_asset_cancellations(asset_id BIGINT PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE acc_asset_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id BIGINT NOT NULL,date TEXT NOT NULL,custodian TEXT NOT NULL,location TEXT NOT NULL,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE acc_asset_policies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,effective_date TEXT NOT NULL,depreciation_budget_charge BIGINT NOT NULL CHECK(depreciation_budget_charge IN(0,1)),reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE acc_asset_policy_approvals(policy_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE acc_assets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,project_id BIGINT NOT NULL,source_id BIGINT NOT NULL,bill_line_id BIGINT,opening_item_id BIGINT,cost BIGINT NOT NULL CHECK(cost>0),residual BIGINT NOT NULL CHECK(residual>=0 AND residual<cost),life_months BIGINT NOT NULL CHECK(life_months BETWEEN 1 AND 1200),acquired_date TEXT NOT NULL,in_service_date TEXT NOT NULL,custodian TEXT NOT NULL,location TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,CHECK((bill_line_id IS NOT NULL)!=(opening_item_id IS NOT NULL)),CHECK(in_service_date>=acquired_date));
CREATE TABLE acc_books(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,active BIGINT NOT NULL CHECK(active IN(0,1)),actor_id BIGINT);
CREATE TABLE acc_cancellations(document_id BIGINT PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE acc_close_authorizations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_id BIGINT NOT NULL,closer_id BIGINT NOT NULL,creator_id BIGINT NOT NULL,expiry TEXT NOT NULL,reason TEXT NOT NULL,fingerprint TEXT NOT NULL,treatments TEXT NOT NULL);
CREATE TABLE acc_close_uses(authorization_id BIGINT PRIMARY KEY,event_id BIGINT NOT NULL UNIQUE);
CREATE TABLE acc_depreciation(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id BIGINT NOT NULL,document_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),through_month TEXT NOT NULL,UNIQUE(asset_id,document_id));
CREATE TABLE acc_disposals(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id BIGINT NOT NULL,document_id BIGINT NOT NULL UNIQUE,proceeds BIGINT NOT NULL CHECK(proceeds>=0),net_book BIGINT NOT NULL CHECK(net_book>=0));
CREATE TABLE acc_documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('manual','opening','recognition','reclassification','funding_refund','allocation_transfer','opening_settlement','asset_depreciation','asset_disposal')),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,book_id BIGINT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL,lines TEXT NOT NULL,charges TEXT NOT NULL,details TEXT NOT NULL,replaces_id BIGINT);
CREATE TABLE acc_evidence(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,bytes BIGINT NOT NULL,sha256 TEXT NOT NULL,content_encrypted TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE acc_fiscal_periods(period_id BIGINT PRIMARY KEY,year_id BIGINT NOT NULL);
CREATE TABLE acc_fiscal_years(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,start_date TEXT NOT NULL,end_date TEXT NOT NULL,actor_id BIGINT,CHECK(start_date<=end_date));
CREATE TABLE acc_fund_approvals(policy_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE acc_fund_policies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,source_id BIGINT NOT NULL,effective_date TEXT NOT NULL,restricted BIGINT NOT NULL CHECK(restricted IN(0,1)),receipt_treatment TEXT NOT NULL CHECK(receipt_treatment IN('income','deferred','refundable')),recognition_basis TEXT NOT NULL CHECK(recognition_basis IN('on_receipt','approved_milestone','eligible_expenditure')),allow_transfers BIGINT NOT NULL CHECK(allow_transfers IN(0,1)),reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE acc_item_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_id BIGINT NOT NULL,journal_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount<>0));
CREATE TABLE acc_journal_info(journal_id BIGINT PRIMARY KEY,book_id BIGINT NOT NULL,currency TEXT NOT NULL CHECK(currency='USD'),original_amount BIGINT NOT NULL,base_amount BIGINT NOT NULL,rate TEXT NOT NULL CHECK(rate='1'),rate_date TEXT NOT NULL,source_kind TEXT NOT NULL,source_record TEXT NOT NULL,CHECK(original_amount=base_amount));
CREATE TABLE acc_line_roles(line_id BIGINT PRIMARY KEY,role TEXT NOT NULL);
CREATE TABLE acc_mappings(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,role TEXT NOT NULL,account_id BIGINT NOT NULL,effective_date TEXT NOT NULL,actor_id BIGINT,reason TEXT NOT NULL);
CREATE TABLE acc_open_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL,account_id BIGINT NOT NULL,project_id BIGINT NOT NULL,source_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),side TEXT NOT NULL CHECK(side IN('debit','credit')),role TEXT NOT NULL,party TEXT NOT NULL,due_date TEXT NOT NULL,employee_id BIGINT,supplier_id BIGINT);
CREATE TABLE acc_period_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('close','reopen')),reason TEXT NOT NULL,actor_id BIGINT NOT NULL,snapshot TEXT NOT NULL);
CREATE TABLE acc_posts(document_id BIGINT PRIMARY KEY,journal_id BIGINT NOT NULL UNIQUE);
CREATE TABLE acc_receipts(journal_id BIGINT PRIMARY KEY,source_id BIGINT NOT NULL,policy_id BIGINT,treatment TEXT NOT NULL CHECK(treatment IN('legacy','income','deferred','refundable')),amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE acc_reopen_approvals(request_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL,event_id BIGINT NOT NULL UNIQUE);
CREATE TABLE acc_reopen_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,period_id BIGINT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,close_event_id BIGINT);
CREATE TABLE acc_roles(user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('accountant','approver','auditor')),PRIMARY KEY(user_id,role));
CREATE TABLE acc_year_approvals(year_end_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE acc_year_ends(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,year_id BIGINT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,snapshot TEXT NOT NULL,previous_id BIGINT);
CREATE TABLE acc_year_reopens(year_end_id BIGINT NOT NULL,period_event_id BIGINT NOT NULL,PRIMARY KEY(year_end_id,period_event_id));
CREATE TABLE account_currencies(account_id BIGINT PRIMARY KEY,currency TEXT NOT NULL);
CREATE TABLE accounts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN('bank','cash','mobile','expense','asset','payable','advance','funding')));
CREATE TABLE advance_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, advance_id BIGINT NOT NULL, request_line_id BIGINT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE advance_requests(request_id BIGINT PRIMARY KEY,beneficiary TEXT NOT NULL,beneficiary_type TEXT NOT NULL CHECK(beneficiary_type IN('employee','supplier')),due_date TEXT NOT NULL);
CREATE TABLE advance_terms(advance_id BIGINT PRIMARY KEY,beneficiary_type TEXT NOT NULL CHECK(beneficiary_type IN('employee','supplier')),due_date TEXT NOT NULL);
CREATE TABLE advances(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id BIGINT NOT NULL UNIQUE, beneficiary TEXT NOT NULL, journal_id BIGINT NOT NULL UNIQUE);
CREATE TABLE approval_rules(kind TEXT PRIMARY KEY CHECK(kind IN('budget','spending')), rules TEXT NOT NULL);
CREATE TABLE approvals(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, kind TEXT NOT NULL, document_id BIGINT NOT NULL, revision BIGINT NOT NULL, level BIGINT NOT NULL, user_id BIGINT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, principal_id BIGINT, delegation_id BIGINT, UNIQUE(kind,document_id,revision,level));
CREATE TABLE attendance(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,date TEXT NOT NULL,minutes BIGINT NOT NULL CHECK(minutes BETWEEN 0 AND 1440),reason TEXT NOT NULL,previous_id BIGINT,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_id BIGINT NOT NULL, action TEXT NOT NULL, entity TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE auth_limits(bucket TEXT PRIMARY KEY,attempts BIGINT NOT NULL,reset_at BIGINT NOT NULL);
CREATE TABLE auth_resets(token_hash TEXT PRIMARY KEY,user_id BIGINT NOT NULL,issuer_id BIGINT NOT NULL,expires BIGINT NOT NULL,used BIGINT NOT NULL DEFAULT 0 CHECK(used IN(0,1)));
CREATE TABLE bill_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bill_id BIGINT NOT NULL, request_line_id BIGINT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE bill_reissues(new_bill_id BIGINT PRIMARY KEY,original_bill_id BIGINT NOT NULL UNIQUE,canonical_invoice TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE bills(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, po_id BIGINT NOT NULL, supplier TEXT NOT NULL, invoice TEXT NOT NULL, journal_id BIGINT NOT NULL UNIQUE, date TEXT NOT NULL, due_date TEXT, UNIQUE(supplier,invoice));
CREATE TABLE budget_changes(budget_id BIGINT PRIMARY KEY,kind TEXT NOT NULL,details TEXT NOT NULL);
CREATE TABLE budget_charges(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_line_id BIGINT NOT NULL, amount BIGINT NOT NULL CHECK(amount<>0), journal_id BIGINT NOT NULL, date TEXT NOT NULL);
CREATE TABLE budget_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, budget_id BIGINT NOT NULL, category TEXT NOT NULL, activity TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0 AND amount<=1000000000000), CHECK(start_date<=end_date));
CREATE TABLE budget_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL, version BIGINT NOT NULL, previous_id BIGINT, reason TEXT NOT NULL, creator_id BIGINT NOT NULL, state TEXT NOT NULL DEFAULT 'submitted' CHECK(state IN('submitted','approved')), approval_policy TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id,version));
CREATE TABLE cash_offset_lines(journal_line_id BIGINT PRIMARY KEY,offset_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE cash_offsets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE closure_authorizations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL,closer_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,expiry TEXT NOT NULL,reason TEXT NOT NULL,fingerprint TEXT NOT NULL,treatments TEXT NOT NULL,CHECK(closer_id<>actor_id));
CREATE TABLE closure_uses(authorization_id BIGINT PRIMARY KEY,event_id BIGINT NOT NULL UNIQUE);
CREATE TABLE comment_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,comment_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('resolve','reopen')),reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE comments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL,kind TEXT NOT NULL,entity_id BIGINT NOT NULL,location TEXT NOT NULL,body TEXT NOT NULL,parent_id BIGINT,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE commitments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_line_id BIGINT NOT NULL, amount BIGINT NOT NULL CHECK(amount<>0), journal_id BIGINT, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, effective_date TEXT);
CREATE TABLE controls(name TEXT PRIMARY KEY,value TEXT NOT NULL,actor_id BIGINT);
CREATE TABLE correction_authorizations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,journal_id BIGINT NOT NULL,poster_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,expiry TEXT NOT NULL,reason TEXT NOT NULL,CHECK(poster_id<>actor_id));
CREATE TABLE correction_uses(authorization_id BIGINT PRIMARY KEY,journal_id BIGINT NOT NULL UNIQUE);
CREATE TABLE credit_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,credit_id BIGINT NOT NULL,bill_line_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),liability_amount BIGINT NOT NULL CHECK(liability_amount>=0),receivable_amount BIGINT NOT NULL CHECK(receivable_amount>=0),restore_commitment BIGINT NOT NULL CHECK(restore_commitment IN(0,1)),CHECK(amount=liability_amount+receivable_amount));
CREATE TABLE credit_notes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,bill_id BIGINT NOT NULL,reference TEXT NOT NULL UNIQUE,journal_id BIGINT NOT NULL UNIQUE,date TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE currency_definitions(code TEXT PRIMARY KEY,scale BIGINT NOT NULL CHECK(scale BETWEEN 0 AND 4));
CREATE TABLE delegation_revocations(delegation_id BIGINT PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE delegations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL,principal_id BIGINT NOT NULL,delegate_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('manager','finance')),start_date TEXT NOT NULL,end_date TEXT NOT NULL,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,CHECK(principal_id<>delegate_id),CHECK(start_date<=end_date));
CREATE TABLE deliveries(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,notification_id BIGINT NOT NULL UNIQUE,channel TEXT NOT NULL,recipient TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN('queued','sending','sent','failed')),attempts BIGINT NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,lease_until BIGINT NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',sent_at TEXT);
CREATE TABLE documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,entity_id BIGINT NOT NULL,projects TEXT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,bytes BIGINT NOT NULL CHECK(bytes>0 AND bytes<=524288),sha256 TEXT NOT NULL,content BYTEA NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE el_access_applied(request_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE el_access_approvals(request_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE el_access_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('local','external')),system TEXT NOT NULL,effective_date TEXT NOT NULL,roles TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_access_revocations(employee_id BIGINT PRIMARY KEY,departure_id BIGINT NOT NULL,date TEXT NOT NULL,user_id BIGINT);
CREATE TABLE el_applications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,vacancy_id BIGINT NOT NULL,candidate_id BIGINT NOT NULL,creator_id BIGINT NOT NULL,UNIQUE(vacancy_id,candidate_id));
CREATE TABLE el_budget_reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,snapshot TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE el_candidates(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,email_hash TEXT NOT NULL UNIQUE,user_id BIGINT,payload_encrypted TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_cases(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,template_id BIGINT NOT NULL,document_id BIGINT,start_date TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_change_links(document_id BIGINT PRIMARY KEY,term_id BIGINT,profile_id BIGINT);
CREATE TABLE el_change_proposals(document_id BIGINT PRIMARY KEY,term_id BIGINT NOT NULL UNIQUE);
CREATE TABLE el_conversions(candidate_id BIGINT PRIMARY KEY,offer_id BIGINT NOT NULL UNIQUE,employee_id BIGINT NOT NULL UNIQUE,actor_id BIGINT NOT NULL);
CREATE TABLE el_departure_advances(document_id BIGINT NOT NULL,advance_id BIGINT NOT NULL UNIQUE,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,PRIMARY KEY(document_id,advance_id));
CREATE TABLE el_departure_closures(document_id BIGINT PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE el_departure_liabilities(document_id BIGINT NOT NULL,expense_id BIGINT NOT NULL UNIQUE,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,PRIMARY KEY(document_id,expense_id));
CREATE TABLE el_departure_links(document_id BIGINT PRIMARY KEY,case_id BIGINT,profile_id BIGINT);
CREATE TABLE el_documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,employee_id BIGINT,creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL,payload_encrypted TEXT NOT NULL,previous_id BIGINT,root_id BIGINT);
CREATE TABLE el_equipment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,reference TEXT NOT NULL UNIQUE,description TEXT NOT NULL,date TEXT NOT NULL,asset_id BIGINT,actor_id BIGINT NOT NULL);
CREATE TABLE el_equipment_returns(equipment_id BIGINT PRIMARY KEY,date TEXT NOT NULL,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE el_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL,kind TEXT NOT NULL,actor_id BIGINT NOT NULL,date TEXT NOT NULL,payload_encrypted TEXT NOT NULL);
CREATE TABLE el_files(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,owner_kind TEXT NOT NULL,owner_id BIGINT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,bytes BIGINT NOT NULL,sha256 TEXT NOT NULL,visibility TEXT NOT NULL CHECK(visibility IN('shared','private')),content_encrypted TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE el_final_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,departure_id BIGINT NOT NULL,policy_id BIGINT NOT NULL,period_id BIGINT NOT NULL,payload_encrypted TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_final_review_approvals(review_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE el_final_reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,departure_id BIGINT NOT NULL,policy_id BIGINT NOT NULL,run_id BIGINT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_final_runs(request_id BIGINT PRIMARY KEY,run_id BIGINT NOT NULL UNIQUE);
CREATE TABLE el_hiring_decisions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL,decision TEXT NOT NULL CHECK(decision IN('selected','rejected','hold')),payload_encrypted TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE el_interview_cancellations(interview_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE el_interviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,application_id BIGINT NOT NULL,panel_id BIGINT NOT NULL,criteria TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,location TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_offer_links(document_id BIGINT PRIMARY KEY,application_id BIGINT NOT NULL,staffing_id BIGINT NOT NULL);
CREATE TABLE el_policies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,rules TEXT NOT NULL,reason TEXT NOT NULL,actor_id BIGINT);
CREATE TABLE el_probation_approvals(review_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE el_probation_reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,probation_id BIGINT NOT NULL,outcome TEXT NOT NULL CHECK(outcome IN('confirm','extend','followup')),new_due_date TEXT,payload_encrypted TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_probations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,due_date TEXT NOT NULL,supervisor_id BIGINT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_qualifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,name TEXT NOT NULL,issuer TEXT NOT NULL,level TEXT NOT NULL,earned_date TEXT NOT NULL,expiry TEXT,training_id BIGINT,file_id BIGINT,actor_id BIGINT NOT NULL);
CREATE TABLE el_retention_policies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,retention_days BIGINT NOT NULL CHECK(retention_days>=1),legal_hold BIGINT NOT NULL CHECK(legal_hold IN(0,1)),reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE el_review_cycles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,due_date TEXT NOT NULL,min_rating BIGINT NOT NULL,max_rating BIGINT NOT NULL,criteria TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_review_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,review_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('self','supervisor','moderation','finalize','acknowledgment','followup')),score BIGINT,payload_encrypted TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE el_reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,cycle_id BIGINT NOT NULL,supervisor_id BIGINT NOT NULL,goals TEXT NOT NULL,previous_id BIGINT,creator_id BIGINT NOT NULL);
CREATE TABLE el_roles(user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('hiring_approver','review_moderator','access_officer')),PRIMARY KEY(user_id,role));
CREATE TABLE el_scores(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,interview_id BIGINT NOT NULL UNIQUE,payload_encrypted TEXT NOT NULL,score BIGINT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE el_self_decisions(request_id BIGINT PRIMARY KEY,decision TEXT NOT NULL CHECK(decision IN('approved','rejected')),reason TEXT NOT NULL,result_kind TEXT,result_id BIGINT,actor_id BIGINT NOT NULL);
CREATE TABLE el_self_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('personal','payment','document')),effective_date TEXT NOT NULL,payload_encrypted TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE el_task_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,task_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('submitted','completed','reopened')),payload_encrypted TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE el_tasks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,case_id BIGINT NOT NULL,title TEXT NOT NULL,kind TEXT NOT NULL,owner_id BIGINT NOT NULL,reviewer_id BIGINT,due_date TEXT NOT NULL,requires_review BIGINT NOT NULL CHECK(requires_review IN(0,1)));
CREATE TABLE el_templates(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('onboarding','departure')),name TEXT NOT NULL,items TEXT NOT NULL,previous_id BIGINT,creator_id BIGINT NOT NULL);
CREATE TABLE el_training_attendance(document_id BIGINT NOT NULL,employee_id BIGINT NOT NULL,attended BIGINT NOT NULL CHECK(attended IN(0,1)),reason TEXT NOT NULL,actor_id BIGINT NOT NULL,PRIMARY KEY(document_id,employee_id));
CREATE TABLE el_training_links(document_id BIGINT PRIMARY KEY,request_id BIGINT NOT NULL UNIQUE,actor_id BIGINT NOT NULL);
CREATE TABLE el_vacancies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,staffing_id BIGINT NOT NULL UNIQUE,reference TEXT NOT NULL UNIQUE,creator_id BIGINT NOT NULL);
CREATE TABLE employee_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('active','inactive')),reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employee_term_approvals(term_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employee_terms(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,previous_id BIGINT,effective_date TEXT NOT NULL,terms_encrypted TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE employees(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,user_id BIGINT UNIQUE,department TEXT NOT NULL,start_date TEXT NOT NULL,terms_encrypted TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE exceptions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), expiry TEXT NOT NULL, reason TEXT NOT NULL, actor_id BIGINT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE expense_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,expense_id BIGINT NOT NULL,request_line_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE expense_payment_lines(payment_id BIGINT NOT NULL,expense_line_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,expense_line_id));
CREATE TABLE expense_payments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,expense_id BIGINT NOT NULL,journal_id BIGINT NOT NULL UNIQUE,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE expenses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,request_id BIGINT NOT NULL,reference TEXT NOT NULL UNIQUE,payee TEXT NOT NULL,due_date TEXT NOT NULL,journal_id BIGINT NOT NULL UNIQUE,date TEXT NOT NULL);
CREATE TABLE foreign_cash_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,journal_line_id BIGINT NOT NULL UNIQUE,currency TEXT NOT NULL,units BIGINT NOT NULL,rate_id BIGINT NOT NULL);
CREATE TABLE foreign_documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,entity_id BIGINT NOT NULL,currency TEXT NOT NULL,units BIGINT NOT NULL,rate_id BIGINT NOT NULL,base_amount BIGINT NOT NULL,rounding TEXT NOT NULL,UNIQUE(kind,entity_id));
CREATE TABLE funding_sources(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id BIGINT NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN('organization','donor')), categories TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, UNIQUE(project_id,name), CHECK(start_date<=end_date));
CREATE TABLE fx_rates(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,currency TEXT NOT NULL,date TEXT NOT NULL,numerator TEXT NOT NULL,denominator TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE grant_activations(grant_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE grant_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,source_id BIGINT NOT NULL,previous_id BIGINT,amount BIGINT NOT NULL CHECK(amount>=0),reason TEXT NOT NULL,creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hr_allocation_approvals(plan_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE hr_allocation_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,plan_id BIGINT NOT NULL,project_id BIGINT NOT NULL,source_id BIGINT NOT NULL,category TEXT NOT NULL,activity TEXT NOT NULL,weight BIGINT NOT NULL CHECK(weight>0),components TEXT NOT NULL);
CREATE TABLE hr_allocation_plans(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE hr_attendance_approvals(review_id BIGINT PRIMARY KEY,attendance_id BIGINT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE hr_attendance_import_posts(import_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE hr_attendance_imports(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reference TEXT NOT NULL UNIQUE,rows_encrypted TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE hr_attendance_reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,date TEXT NOT NULL,minutes BIGINT NOT NULL CHECK(minutes BETWEEN 0 AND 1440),previous_id BIGINT,reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE hr_batch_details(batch_id BIGINT NOT NULL,employee_id BIGINT NOT NULL,details_id BIGINT NOT NULL,PRIMARY KEY(batch_id,employee_id));
CREATE TABLE hr_batch_posts(batch_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE hr_batch_vouchers(batch_id BIGINT NOT NULL,voucher_id BIGINT NOT NULL UNIQUE,PRIMARY KEY(batch_id,voucher_id));
CREATE TABLE hr_documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,bytes BIGINT NOT NULL,sha256 TEXT NOT NULL,content_encrypted TEXT NOT NULL,expiry TEXT,visibility TEXT NOT NULL CHECK(visibility IN('hr','employee','supervisor')),actor_id BIGINT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hr_holidays(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,schedule_id BIGINT NOT NULL,date TEXT NOT NULL,name TEXT NOT NULL,actor_id BIGINT NOT NULL,UNIQUE(schedule_id,date));
CREATE TABLE hr_leave_cancellations(request_id BIGINT PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE hr_leave_enrollments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,policy_id BIGINT NOT NULL,start_date TEXT NOT NULL,opening_minutes BIGINT NOT NULL,actor_id BIGINT NOT NULL,UNIQUE(employee_id,policy_id));
CREATE TABLE hr_leave_links(request_id BIGINT PRIMARY KEY,enrollment_id BIGINT NOT NULL,minutes BIGINT NOT NULL,calendar_snapshot TEXT NOT NULL);
CREATE TABLE hr_leave_policies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,paid BIGINT NOT NULL CHECK(paid IN(0,1)),opening_minutes BIGINT NOT NULL,monthly_minutes BIGINT NOT NULL,carryover_cap BIGINT NOT NULL,expiry_months BIGINT NOT NULL,eligibility_days BIGINT NOT NULL,policy_state TEXT NOT NULL CHECK(policy_state IN('demo','provisional','validated')),validation_reference TEXT NOT NULL,creator_id BIGINT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE hr_leave_policy_approvals(policy_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE hr_overtime(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,period_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE hr_overtime_approvals(overtime_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE hr_payment_approvals(details_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE hr_payment_batches(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reference TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE hr_payment_controls(payment_id BIGINT NOT NULL,allocation_id BIGINT NOT NULL,account_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,allocation_id,account_id));
CREATE TABLE hr_payment_details(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,effective_date TEXT NOT NULL,details_encrypted TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE hr_payroll_context(run_id BIGINT PRIMARY KEY,period_id BIGINT NOT NULL,inputs_encrypted TEXT NOT NULL,fingerprint TEXT NOT NULL);
CREATE TABLE hr_payroll_controls(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id BIGINT NOT NULL,allocation_id BIGINT NOT NULL,account_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE hr_payroll_recoveries(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id BIGINT NOT NULL,allocation_id BIGINT NOT NULL,advance_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE hr_periods(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,start_date TEXT NOT NULL,end_date TEXT NOT NULL,posting_date TEXT NOT NULL,creator_id BIGINT NOT NULL,CHECK(start_date<=end_date AND posting_date>=end_date));
CREATE TABLE hr_profiles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,effective_date TEXT NOT NULL,schedule_id BIGINT NOT NULL,supervisor_id BIGINT,department TEXT NOT NULL,position TEXT NOT NULL,location TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('joining','active','transferred','departed')),private_encrypted TEXT NOT NULL,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE hr_roles(user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('hr_staff','supervisor','payroll_preparer','payroll_approver','payroll_finance')),PRIMARY KEY(user_id,role));
CREATE TABLE hr_rule_status(rule_id BIGINT PRIMARY KEY,policy_state TEXT NOT NULL CHECK(policy_state IN('demo','provisional','validated')),validation_reference TEXT NOT NULL);
CREATE TABLE hr_salary_advance_posts(advance_id BIGINT PRIMARY KEY,journal_id BIGINT NOT NULL UNIQUE);
CREATE TABLE hr_salary_advances(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,project_id BIGINT NOT NULL,source_id BIGINT NOT NULL,category TEXT NOT NULL,activity TEXT NOT NULL,account_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,repayment_schedule TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL);
CREATE TABLE hr_salary_returns(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,advance_id BIGINT NOT NULL,journal_id BIGINT NOT NULL UNIQUE,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE hr_schedules(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,weekdays TEXT NOT NULL,start_minute BIGINT NOT NULL,end_minute BIGINT NOT NULL,break_minutes BIGINT NOT NULL,actor_id BIGINT NOT NULL,CHECK(start_minute>=0 AND end_minute<=1440 AND start_minute<end_minute),CHECK(break_minutes>=0 AND break_minutes<end_minute-start_minute));
CREATE TABLE hr_time_approvals(timesheet_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE hr_time_cancellations(timesheet_id BIGINT PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE hr_time_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,timesheet_id BIGINT NOT NULL,date TEXT NOT NULL,start_minute BIGINT NOT NULL,end_minute BIGINT NOT NULL,project_id BIGINT NOT NULL,source_id BIGINT NOT NULL,category TEXT NOT NULL,activity TEXT NOT NULL,CHECK(start_minute>=0 AND end_minute<=1440 AND start_minute<end_minute));
CREATE TABLE hr_timesheets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,period_id BIGINT NOT NULL,reference TEXT NOT NULL UNIQUE,creator_id BIGINT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE integration_events(integration_id BIGINT NOT NULL,external_id TEXT NOT NULL,payload_hash TEXT NOT NULL,result TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(integration_id,external_id));
CREATE TABLE integration_outbox(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,integration_id BIGINT NOT NULL,event_key TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'queued',attempts BIGINT NOT NULL DEFAULT 0,lease_until BIGINT NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',delivered_at TEXT,UNIQUE(integration_id,event_key));
CREATE TABLE integration_routes(integration_id BIGINT NOT NULL,external_source TEXT NOT NULL,source_id BIGINT NOT NULL,account_id BIGINT NOT NULL,poster_id BIGINT NOT NULL,PRIMARY KEY(integration_id,external_source));
CREATE TABLE integrations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL UNIQUE,endpoint TEXT NOT NULL,secret_encrypted TEXT NOT NULL,enabled BIGINT NOT NULL CHECK(enabled IN(0,1)),actor_id BIGINT NOT NULL);
CREATE TABLE items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,unit TEXT NOT NULL,category TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE "journal_lines"(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,journal_id BIGINT NOT NULL,account_id BIGINT NOT NULL,project_id BIGINT,source_id BIGINT,amount BIGINT NOT NULL CHECK(amount<>0 AND abs(amount)<=1000000000000),org_fund_id BIGINT,department_id BIGINT,cost_centre_id BIGINT,CHECK((project_id IS NOT NULL AND source_id IS NOT NULL AND org_fund_id IS NULL) OR (project_id IS NULL AND source_id IS NULL AND org_fund_id IS NOT NULL)));
CREATE TABLE journal_proposal_posts(proposal_id BIGINT PRIMARY KEY,journal_id BIGINT NOT NULL UNIQUE);
CREATE TABLE journal_proposals(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,original_id BIGINT NOT NULL,reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL,lines TEXT NOT NULL,charges TEXT NOT NULL,authorization_id BIGINT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE journals(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, kind TEXT NOT NULL, reference TEXT NOT NULL UNIQUE, date TEXT NOT NULL, description TEXT NOT NULL, actor_id BIGINT NOT NULL, state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN('draft','posted')), reversal_of BIGINT UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leave_decisions(leave_id BIGINT PRIMARY KEY,decision TEXT NOT NULL CHECK(decision IN('approved','rejected')),reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE leave_pay_classifications(request_id BIGINT PRIMARY KEY,paid BIGINT NOT NULL CHECK(paid IN(0,1)),actor_id BIGINT NOT NULL);
CREATE TABLE leave_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_id BIGINT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,type TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(start_date<=end_date));
CREATE TABLE match_reversals(match_id BIGINT PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memberships(project_id BIGINT NOT NULL, user_id BIGINT NOT NULL, role TEXT NOT NULL CHECK(role IN('requester','manager','finance','viewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE mfa_consumptions(user_id BIGINT NOT NULL,counter BIGINT NOT NULL,PRIMARY KEY(user_id,counter));
CREATE TABLE mfa_recovery(user_id BIGINT NOT NULL,code_hash TEXT PRIMARY KEY,consumed BIGINT NOT NULL DEFAULT 0 CHECK(consumed IN(0,1)));
CREATE TABLE notification_reads(notification_id BIGINT NOT NULL,user_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(notification_id,user_id));
CREATE TABLE notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,project_id BIGINT,kind TEXT NOT NULL,entity_id BIGINT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,dedupe TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE oidc_attempts(token_hash TEXT PRIMARY KEY,payload_encrypted TEXT NOT NULL,expires BIGINT NOT NULL,used BIGINT NOT NULL DEFAULT 0,user_id BIGINT,verified BIGINT NOT NULL DEFAULT 0, provider_mfa BIGINT NOT NULL DEFAULT 0 CHECK(provider_mfa IN(0,1)));
CREATE TABLE oidc_identities(issuer TEXT NOT NULL,subject TEXT NOT NULL,user_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(issuer,subject),UNIQUE(issuer,user_id));
CREATE TABLE operations(user_id BIGINT NOT NULL, key TEXT NOT NULL, payload_hash TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(user_id,key));
CREATE TABLE ops_connections(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('scim','calendar')),name TEXT NOT NULL UNIQUE,endpoint TEXT NOT NULL,secret_encrypted TEXT NOT NULL,enabled BIGINT NOT NULL CHECK(enabled IN(0,1)),actor_id BIGINT NOT NULL);
CREATE TABLE ops_erasure_permits(table_name TEXT NOT NULL,row_id BIGINT NOT NULL,run_id BIGINT NOT NULL,PRIMARY KEY(table_name,row_id));
CREATE TABLE ops_erasures(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,record_id BIGINT NOT NULL,rule_id BIGINT NOT NULL,run_id BIGINT NOT NULL,summary TEXT NOT NULL,generation BIGINT NOT NULL DEFAULT 0,UNIQUE(kind,record_id,generation));
CREATE TABLE ops_final_calculations(request_id BIGINT PRIMARY KEY,inputs_encrypted TEXT NOT NULL,fingerprint TEXT NOT NULL);
CREATE TABLE ops_holds(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,record_id BIGINT NOT NULL,enabled BIGINT NOT NULL CHECK(enabled IN(0,1)),reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_policy_formulas(document_id BIGINT PRIMARY KEY,jurisdiction TEXT NOT NULL,formulas TEXT NOT NULL,agreement TEXT NOT NULL);
CREATE TABLE ops_provider_checks(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id BIGINT,kind TEXT NOT NULL,ok BIGINT NOT NULL CHECK(ok IN(0,1)),detail TEXT NOT NULL,config_hash TEXT NOT NULL DEFAULT '',actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_provider_identities(connection_id BIGINT NOT NULL,employee_id BIGINT NOT NULL,external_id TEXT NOT NULL,episode_id BIGINT,PRIMARY KEY(connection_id,employee_id),UNIQUE(connection_id,external_id));
CREATE TABLE ops_provider_jobs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,connection_id BIGINT NOT NULL,event_key TEXT NOT NULL UNIQUE,kind TEXT NOT NULL,payload_encrypted TEXT NOT NULL,actor_id BIGINT NOT NULL,state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN('queued','sending','sent','failed')),attempts BIGINT NOT NULL DEFAULT 0,next_attempt BIGINT NOT NULL DEFAULT 0,lease_until BIGINT NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',external_id TEXT,completed_at TEXT);
CREATE TABLE ops_rehire_proposals(document_id BIGINT PRIMARY KEY,departure_id BIGINT NOT NULL,term_id BIGINT NOT NULL UNIQUE);
CREATE TABLE ops_rehires(document_id BIGINT PRIMARY KEY,departure_id BIGINT NOT NULL UNIQUE,employee_id BIGINT NOT NULL,start_date TEXT NOT NULL,profile_id BIGINT NOT NULL,access_enabled BIGINT NOT NULL CHECK(access_enabled IN(0,1)));
CREATE TABLE ops_retention_approvals(rule_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE ops_retention_rules(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('candidate','review','employee_document','employment')),days BIGINT NOT NULL CHECK(days BETWEEN 1 AND 36500),effective_date TEXT NOT NULL,legal_basis TEXT NOT NULL,automatic BIGINT NOT NULL CHECK(automatic IN(0,1)),creator_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_retention_runs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor_id BIGINT NOT NULL,date TEXT NOT NULL,automatic BIGINT NOT NULL CHECK(automatic IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ops_revocations(departure_id BIGINT PRIMARY KEY,employee_id BIGINT NOT NULL,user_id BIGINT,date TEXT NOT NULL);
CREATE TABLE ops_roles(user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role='privacy_officer'),PRIMARY KEY(user_id,role));
CREATE TABLE ops_setup_runs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,configuration TEXT NOT NULL,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE org_allocations(document_id BIGINT PRIMARY KEY,origin_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE org_asset_approvals(asset_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE org_asset_cancellations(asset_id BIGINT PRIMARY KEY,reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE org_asset_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,asset_id BIGINT NOT NULL,document_id BIGINT NOT NULL UNIQUE,journal_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('depreciation','disposal')),amount BIGINT NOT NULL,through_month TEXT);
CREATE TABLE org_asset_register(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL UNIQUE,cost_id BIGINT NOT NULL UNIQUE,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,cost BIGINT NOT NULL,residual BIGINT NOT NULL,life_months BIGINT NOT NULL,in_service_date TEXT NOT NULL,custodian TEXT NOT NULL,location TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE org_budget_approvals(budget_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE org_budget_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL,name TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('independent','parent')),department_id BIGINT,cost_centre_id BIGINT,project_ids TEXT NOT NULL,lines TEXT NOT NULL,previous_id BIGINT,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL);
CREATE TABLE org_costs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL,journal_id BIGINT NOT NULL,budget_code TEXT,category TEXT NOT NULL,org_fund_id BIGINT,department_id BIGINT,cost_centre_id BIGINT,project_id BIGINT,request_line_id BIGINT,amount BIGINT NOT NULL CHECK(amount<>0),origin_id BIGINT);
CREATE TABLE org_documents(document_id BIGINT PRIMARY KEY,kind TEXT NOT NULL,spec TEXT NOT NULL);
CREATE TABLE org_fund_approvals(fund_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE org_funds(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,restricted BIGINT NOT NULL CHECK(restricted IN(0,1)),categories TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,treatment TEXT NOT NULL CHECK(treatment IN('income','deferred','refundable')),recognize_receivable BIGINT NOT NULL CHECK(recognize_receivable IN(0,1)),allow_transfers BIGINT NOT NULL CHECK(allow_transfers IN(0,1)),reason TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE org_item_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,item_id BIGINT NOT NULL,document_id BIGINT NOT NULL UNIQUE,journal_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),kind TEXT NOT NULL);
CREATE TABLE org_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN('bill','reimbursement','receivable','advance')),party TEXT NOT NULL,external_reference TEXT NOT NULL,date TEXT NOT NULL,due_date TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),UNIQUE(kind,party,external_reference));
CREATE TABLE org_promise_posts(document_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE org_reservations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL,budget_code TEXT NOT NULL,category TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount<>0),date TEXT NOT NULL,journal_id BIGINT);
CREATE TABLE org_roles(user_id BIGINT NOT NULL,role TEXT NOT NULL CHECK(role IN('hr','payroll','auditor','integration')),PRIMARY KEY(user_id,role));
CREATE TABLE org_schedule_drafts(schedule_id BIGINT NOT NULL,occurrence TEXT NOT NULL,document_id BIGINT NOT NULL UNIQUE,PRIMARY KEY(schedule_id,occurrence));
CREATE TABLE org_schedules(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,template TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,creator_id BIGINT NOT NULL);
CREATE TABLE org_units(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('department','cost_centre','category')),code TEXT NOT NULL,name TEXT NOT NULL,actor_id BIGINT,UNIQUE(kind,code));
CREATE TABLE payment_allocations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, payment_id BIGINT NOT NULL, bill_line_id BIGINT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE payments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, bill_id BIGINT NOT NULL, journal_id BIGINT NOT NULL UNIQUE, account_id BIGINT NOT NULL, reference TEXT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), UNIQUE(account_id,reference));
CREATE TABLE payroll_allocations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id BIGINT NOT NULL,employee_id BIGINT NOT NULL,project_id BIGINT NOT NULL,source_id BIGINT NOT NULL,category TEXT NOT NULL,activity TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),net BIGINT NOT NULL CHECK(net>=0),tax BIGINT NOT NULL CHECK(tax>=0),CHECK(amount=net+tax));
CREATE TABLE payroll_payment_lines(payment_id BIGINT NOT NULL,allocation_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),PRIMARY KEY(payment_id,allocation_id));
CREATE TABLE payroll_payments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,run_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('net','tax')),journal_id BIGINT NOT NULL UNIQUE,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE payroll_posts(run_id BIGINT PRIMARY KEY,journal_id BIGINT NOT NULL UNIQUE);
CREATE TABLE payroll_reservations(run_id BIGINT PRIMARY KEY,request_id BIGINT NOT NULL UNIQUE);
CREATE TABLE payroll_rule_approvals(rule_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL);
CREATE TABLE payroll_rules(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,jurisdiction TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,rules TEXT NOT NULL,reason TEXT NOT NULL,creator_id BIGINT NOT NULL,demo BIGINT NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(start_date<=end_date));
CREATE TABLE payroll_runs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,reference TEXT NOT NULL UNIQUE,period TEXT NOT NULL,date TEXT NOT NULL,rule_id BIGINT NOT NULL,creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL,results_encrypted TEXT NOT NULL,replaces_id BIGINT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE periods(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, start_date TEXT NOT NULL, end_date TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('open','closed')), CHECK(start_date<=end_date));
CREATE TABLE po_suppliers(po_id BIGINT PRIMARY KEY,supplier_id BIGINT NOT NULL);
CREATE TABLE project_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL,kind TEXT NOT NULL,reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE projects(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL, manager_id BIGINT NOT NULL, department TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','closed')), activities TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'), demo BIGINT NOT NULL DEFAULT 0, operational_state TEXT NOT NULL DEFAULT 'open' CHECK(operational_state IN('open','completed')), CHECK(start_date<=end_date));
CREATE TABLE promise_adjustments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,promise_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount<0),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE promises(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, source_id BIGINT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), reference TEXT NOT NULL UNIQUE, date TEXT NOT NULL);
CREATE TABLE purchase_orders(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id BIGINT NOT NULL UNIQUE, supplier TEXT NOT NULL, reference TEXT NOT NULL UNIQUE, date TEXT NOT NULL, created_by BIGINT NOT NULL);
CREATE TABLE reconciliations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, account_id BIGINT NOT NULL, date TEXT NOT NULL, statement_balance BIGINT NOT NULL, outstanding TEXT NOT NULL, difference BIGINT NOT NULL, actor_id BIGINT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, line_watermark BIGINT NOT NULL DEFAULT 0);
CREATE TABLE refund_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,refund_id BIGINT NOT NULL,credit_line_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE release_environment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK(id=1),quarantined BIGINT NOT NULL DEFAULT 0 CHECK(quarantined IN(0,1)),reason TEXT NOT NULL);
CREATE TABLE release_final_review_evidence(review_id BIGINT PRIMARY KEY,inputs_encrypted TEXT NOT NULL,fingerprint TEXT NOT NULL);
CREATE TABLE request_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, request_id BIGINT NOT NULL, project_id BIGINT NOT NULL, source_id BIGINT NOT NULL, category TEXT NOT NULL, activity TEXT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0 AND amount<=1000000000000));
CREATE TABLE request_modes(request_id BIGINT PRIMARY KEY,mode TEXT NOT NULL CHECK(mode IN('expense','payroll')));
CREATE TABLE requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title TEXT NOT NULL, creator_id BIGINT NOT NULL, date TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'submitted' CHECK(state IN('submitted','approved','cancelled')), approval_policy TEXT NOT NULL, revision BIGINT NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, supersedes_id BIGINT, kind TEXT NOT NULL DEFAULT 'purchase' CHECK(kind IN('purchase','advance')));
CREATE TABLE schema_migrations(name TEXT PRIMARY KEY, applied_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id BIGINT NOT NULL, expires BIGINT NOT NULL, auth_strength BIGINT NOT NULL DEFAULT 1 CHECK(auth_strength IN(1,2)));
CREATE TABLE settlements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, advance_id BIGINT NOT NULL, request_line_id BIGINT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), kind TEXT NOT NULL CHECK(kind IN('settlement','return')), journal_id BIGINT NOT NULL, evidence TEXT NOT NULL);
CREATE TABLE statement_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,statement_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('finalize','reopen')),reason TEXT NOT NULL,actor_id BIGINT NOT NULL,line_watermark BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE statement_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,statement_id BIGINT NOT NULL,account_id BIGINT NOT NULL,external_id TEXT NOT NULL,date TEXT NOT NULL,description TEXT NOT NULL,amount BIGINT NOT NULL CHECK(amount<>0),UNIQUE(account_id,external_id));
CREATE TABLE statement_matches(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,statement_line_id BIGINT NOT NULL,journal_line_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE statement_reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id BIGINT NOT NULL,journal_line_id BIGINT NOT NULL,amount BIGINT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE statements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,account_id BIGINT NOT NULL,reference TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,opening_balance BIGINT NOT NULL,closing_balance BIGINT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(account_id,reference),CHECK(start_date<=end_date));
CREATE TABLE stock_cancellations(document_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE stock_document_lines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,to_warehouse_id BIGINT,item_id BIGINT NOT NULL,bill_line_id BIGINT,lot_id BIGINT,quantity BIGINT NOT NULL CHECK(quantity<>0),amount BIGINT NOT NULL CHECK(amount>0),expected_quantity BIGINT,expected_amount BIGINT,source_id BIGINT NOT NULL);
CREATE TABLE stock_documents(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('receipt','issue','transfer','count','return','reversal')),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,reason TEXT NOT NULL,recipient TEXT NOT NULL DEFAULT '',creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL,reversal_of BIGINT UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE stock_movements(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,document_id BIGINT NOT NULL,lot_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,quantity BIGINT NOT NULL CHECK(quantity<>0),amount BIGINT NOT NULL CHECK(amount<>0),date TEXT NOT NULL);
CREATE TABLE stock_posts(document_id BIGINT PRIMARY KEY,journal_id BIGINT NOT NULL UNIQUE);
CREATE TABLE supplier_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,supplier_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('active','inactive')),reason TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE supplier_refunds(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,credit_id BIGINT NOT NULL,account_id BIGINT NOT NULL,reference TEXT NOT NULL,journal_id BIGINT NOT NULL UNIQUE,amount BIGINT NOT NULL CHECK(amount>0),UNIQUE(account_id,reference));
CREATE TABLE suppliers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL UNIQUE,contact TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE user_access_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,enabled BIGINT NOT NULL CHECK(enabled IN(0,1)),reason TEXT NOT NULL,actor_id BIGINT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_mfa(user_id BIGINT PRIMARY KEY,secret_encrypted TEXT NOT NULL,enabled BIGINT NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)));
CREATE TABLE users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, salt TEXT NOT NULL, password_hash TEXT NOT NULL, admin BIGINT NOT NULL DEFAULT 0 CHECK(admin IN(0,1)));
CREATE TABLE voucher_allocations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,voucher_id BIGINT NOT NULL,project_id BIGINT NOT NULL,source_id BIGINT NOT NULL,allocation_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0));
CREATE TABLE voucher_cancellations(voucher_id BIGINT PRIMARY KEY,actor_id BIGINT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE voucher_posts(voucher_id BIGINT PRIMARY KEY,journal_id BIGINT NOT NULL UNIQUE);
CREATE TABLE vouchers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,target_kind TEXT NOT NULL CHECK(target_kind IN('bill','expense','payroll_net','payroll_tax')),target_id BIGINT NOT NULL,account_id BIGINT NOT NULL,amount BIGINT NOT NULL CHECK(amount>0),reference TEXT NOT NULL, date TEXT NOT NULL,creator_id BIGINT NOT NULL,approval_policy TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(account_id,reference));
CREATE TABLE warehouses(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,project_id BIGINT NOT NULL,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,actor_id BIGINT NOT NULL);
CREATE TABLE work_approvals(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,kind TEXT NOT NULL,document_id BIGINT NOT NULL,level BIGINT NOT NULL,actor_id BIGINT NOT NULL,principal_id BIGINT,delegation_id BIGINT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(kind,document_id,level));
CREATE TABLE work_policies(kind TEXT PRIMARY KEY,rules TEXT NOT NULL);
