CREATE FUNCTION "guard_journal_no_update"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $$ BEGIN IF OLD.state='posted' THEN RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Posted journal is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER "journal_no_update" BEFORE UPDATE ON "journals" FOR EACH ROW EXECUTE FUNCTION "guard_journal_no_update"();
